<?php
require_once __DIR__.'/crm-write.php';
if(!function_exists('g93_resend')){function g93_resend($payload){if(!defined('RESEND_API_KEY')||!RESEND_API_KEY)return ['ok'=>false,'skipped'=>true,'error'=>'Resend not configured'];$ch=curl_init('https://api.resend.com/emails');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>g93_json($payload),CURLOPT_HTTPHEADER=>['Authorization: Bearer '.RESEND_API_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>15]);$body=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);return ['ok'=>$http>=200&&$http<300,'http'=>$http,'body'=>$body,'error'=>$err];}}
if(!function_exists('g93_town_blog')){function g93_town_blog($town){$town=trim($town);if(!$town)return 'https://www.markpires.com/blog/';$slug=strtolower(preg_replace('/[^a-z0-9]+/','-',trim($town)));$slug=trim($slug,'-');return 'https://www.markpires.com/blog/'.$slug.'-ct-living-guide.html';}}
if(!function_exists('g93_send_acknowledgement')){function g93_send_acknowledgement($lead,$crmId){$from=defined('RESEND_FROM_EMAIL')?RESEND_FROM_EMAIL:(defined('MARK_EMAIL')?MARK_EMAIL:'mark@markpires.com');$toMark=defined('MARK_EMAIL')?MARK_EMAIL:'mark@markpires.com';$markPhone=defined('MARK_PHONE')?MARK_PHONE:'203-247-2655';$first=$lead['name']?explode(' ',$lead['name'])[0]:'there';$blog=g93_town_blog($lead['town']);$adminHtml='<h2>New Revenue Lead</h2><p><b>Name:</b> '.htmlspecialchars($lead['name']).'</p><p><b>Email:</b> '.htmlspecialchars($lead['email']).'</p><p><b>Phone:</b> '.htmlspecialchars($lead['phone']).'</p><p><b>Address:</b> '.htmlspecialchars($lead['address']).'</p><p><b>Town:</b> '.htmlspecialchars($lead['town']).'</p><p><b>Type:</b> '.htmlspecialchars($lead['type']).'</p><p><b>Score:</b> '.htmlspecialchars($lead['lead_score']).'</p><p><b>Message:</b> '.nl2br(htmlspecialchars($lead['message'])).'</p><p><b>CRM ID:</b> '.htmlspecialchars((string)$crmId).'</p>';$admin=g93_resend(['from'=>'Goliath Revenue Engine <'.$from.'>','to'=>[$toMark],'subject'=>'New MarkPires.com Lead — Score '.$lead['lead_score'],'html'=>$adminHtml]);$user=['ok'=>false,'skipped'=>true,'error'=>'No user email'];if(!empty($lead['email'])){$html='<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;color:#111827;line-height:1.6"><h2 style="color:#1a1a2e">Hi '.htmlspecialchars($first).',</h2><p>Thanks for reaching out. I received your request and I’ll personally follow up soon.</p>'.($lead['town']?'<p>Since you mentioned <b>'.htmlspecialchars($lead['town']).'</b>, I wanted to share this local guide while I review your request:<br><a href="'.htmlspecialchars($blog).'">'.htmlspecialchars($blog).'</a></p>':'').'<p>If anything is urgent, call or text me directly at <b>'.htmlspecialchars($markPhone).'</b>.</p><p>Best,<br><b>Mark Pires</b><br>'.htmlspecialchars($markPhone).'<br>mark@markpires.com</p></div>';$user=g93_resend(['from'=>'Mark Pires <'.$from.'>','to'=>[$lead['email']],'subject'=>'Thanks for reaching out — Mark Pires','html'=>$html]);}if($admin['ok'])g93_timeline($lead['lead_uid'],$crmId,'Jessica','mark_notified','Mark notified by email','Admin notification sent.',$admin);else g93_log_failure($lead['lead_uid'],'admin_email',$admin['error']??'Admin email failed',$admin);if($user['ok'])g93_timeline($lead['lead_uid'],$crmId,'Jessica','thank_you_sent','Thank-you email sent','Initial acknowledgement sent to lead.',$user);else g93_log_failure($lead['lead_uid'],'thank_you_email',$user['error']??'Thank you email skipped/failed',$user,'info');return ['admin'=>$admin,'user'=>$user,'blog'=>$blog];}}
?>
